contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr) public payable {
        require(logAddr != address(0));

        uint minBefore = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool revertedInit;
        c.Initialized(); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedInit = true; } else { revertedInit = false; }

        uint minAfter = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(minAfter == minBefore && (reverted || !revertedInit));
    }

    receive() external payable {}
}

